// ==========================================
// ChatListCompany.jsx
// ==========================================

import React, { useEffect, useState } from "react";
import { useSelector } from "react-redux";
import axios from "axios";
import "../Styles/Chat.css";
import { useNavigate } from "react-router-dom";
import * as ENV from "../config";

const ChatListCompany = () => {
  const { user } = useSelector((state) => state.users); // Logged company
  const navigate = useNavigate();

  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);

  // Load all applications related to this company
  useEffect(() => {
    const fetchCompanyChats = async () => {
      try {
        const res = await axios.get(
          `${ENV.SERVER_URL}/company-applications/${user.email}`
        );
        setApplications(res.data);
      } catch (err) {
        console.log("Error loading chats:", err);
      }
      setLoading(false);
    };

    if (user?.email) fetchCompanyChats();
  }, [user]);

  if (loading) return <p className="loading">Loading chats...</p>;

  return (
    <div className="chatlist-container">
      <h2 className="chat-title">
        Company <span className="accent">Messages</span>
      </h2>

      {applications.length === 0 ? (
        <p className="no-chats">No active chat conversations yet.</p>
      ) : (
        <div className="chatlist-box">
          {applications.map((app) => (
            <div className="chatlist-item" key={app._id}>
              <div className="chatlist-info">
                <h3 className="job-title">{app.jobTitle}</h3>
                <p className="applicant-name">From: {app.applicantName}</p>
                <p className="email">{app.applicantEmail}</p>
              </div>

              <button
                className="open-chat-btn"
                onClick={() => navigate(`/company-chat/${app._id}`)}
              >
                Open Chat 💬
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ChatListCompany;
